head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.selBzProcsNo = "";
scwin.selPrtDepoId = "";
scwin.selExerSeq = "";
scwin.isGongsi = "";
scwin.clickListProcsStatCd = "";
scwin.checkedIndexList = "";
scwin.isFirst = true;
scwin.belngDepCd =  $c.session.getUserInfo("belngDepCd");
scwin.depCd = $c.session.getUserInfo("depCd");
scwin.market = $c.session.getUserInfo("market");

scwin.clickBzProcsNo,

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await $c.cm.searchIsurCode(acb_isurCd, ibx_isurCdNm);
        btn_Input.hide();
        // 2600 유가공시부, 3400 코스닥공시부
        if (scwin.belngDepCd ==="2600" || scwin.belngDepCd ==="3400") {
            btn_Modify.hide();
        // 2500 유가상장부, 3300 코스닥 상장부
        }else if(scwin.belngDepCd ==="2500" || scwin.belngDepCd ==="3300"){
            btn_Modify.hide();
        }else{
            btn_Input.hide();
            btn_Modify.hide();
            // grd_list.setColumnRead(0, true)
            //	grd_Grid.ColumnProp("CHK_YN", "edit") = "any";
        }

        if(scwin.depCd  === 'ZSYS' ){
            btn_Input.show();
            btn_Modify.show();
        // grd_list.setColumnRead(0, true)
        //	grd_Grid.ColumnProp("CHK_YN", "edit") = "any";
        }

        // //신주추가상장에서 호출
        // if(vIsurCd!= null && vIsurCd.length > 0){
        // 	setObjectValue(txb_ISUR_CD, vIsurCd);
        // 	setObjectValue(txb_COM_NM, vComNm);
        // 	txb_ISUR_CD.readOnly = true;
        // 	txb_ISUR_CD.disabled = true;
        // 	txb_ISUR_CD.style.backgroundColor = "#b9d4f7";
        // 	showObj(img_COM_NM, false);
        // 	fn_list_sync();
        // }

        // 해당 그룹 안의 컴포넌트에서 엔터키가 발생하면 해당 컴포넌트의 값을 DataCollection에 저장하고 objFunc 함수를 실행한다.
        $c.win.setEnterKeyEvent(tbl_search, scwin.btn_Search_onclick);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40003.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 조회버튼클릭 — 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick =  async function (e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40003.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 엑셀다운로드클릭 — 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function(e) {
    try {
        // 엑셀다운
        if (grd_list.getRowCount() <= 0) {
                    $c.win.alert("조회된 데이터가 없습니다.");
                    return;
            }
        $c.data.downloadGridViewExcel(grd_list, {fileName: "주식매수선택권 의무보유 관리", sheetName: "shhet1"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40003.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e) {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40003.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        // txb_TotCnt.value = "총 " + rowcount + "건";
        if (rowcount <= 0) {

            dts_List.ClearData();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40003.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description btn_Input 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Input_onclick = function(e) {
    try {
        scwin.selBzProcsNo = "";
        scwin.selPrtDepoId = "";
        scwin.selExerSeq = "";

        const options = {
            id: "ULDSTF40004",
            title: "주식매수선택권 의무보유 관리 상세내역 등록",
            type: "browserPopup",
            width: "790px",
            height: "350px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF40004.gfm", options);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40003.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description scwin.btn_Input_onclick
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Input_onclick = function(e) {
    try {
        scwin.opeonPopup("C");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40003.btn_Input_onclick" });
    }
};

