/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd_com_isur 키 입력 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
