};

/**
 * @method
 * @func
 * @name scwin.btn_Modify_onclick
 * @description scwin.btn_Modify_onclick
 * @returns {void}
 * @hidden N
 */
scwin.btn_Modify_onclick = async function(e) {
    try {
        const rowCheck = scwin.checkChecked();
        const rowPos = dlt_stockoptionRes.getRowPosition();

        if (rowCheck.length > 0) {
            if (rowCheck.length > 1) {
                $c.win.alert("하나만 수정할 수 있습니다.");
            } else {

                const payDd = dlt_stockoptionRes.getCellData(rowPos, "stkoptDutyExerPayDd");

                if (scwin.depCd !== 'ZSYS' && ( payDd === "" ||  payDd === null )) {
                    $c.win.alert("수정할 납입일 정보가 없습니다");
                    return;
                }
                const res =  await $c.win.confirm("선택된 항목의 납입일, 행사주식수만 수정됩니다.\n진행하시겠습니까?")
                if (res) {
                    scwin.isGongsi = true;

                    scwin.selBzProcsNo =  dlt_stockoptionRes.getCellData(rowPos, "bzProcsNo");
                    scwin.selPrtDepoId =  dlt_stockoptionRes.getCellData(rowPos, "prtdepoId");
                    scwin.selExerSeq   =  dlt_stockoptionRes.getCellData(rowPos, "stkoptDutyExerSeq");

                    scwin.opeonPopup("U");

                }
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40003.btn_Modify_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_oncheckclick
 * @description grd_Grid oncheckclick 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_oncheckclick = function(rowIndex, columnIndex, columnId) {
    try {
        // checkOnly(col, bCheck);
        const bCheck = dlt_stockoptionRes.getCellData(rowIndex, "chkYn")
        if(columnId === "chkYn") {
            scwin.checkValid(rowIndex, bCheck);
        }

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40003.grd_Grid_oncheckclick" });
    }
};

/**
 * @method
 * @event
 * @name scwin.btn_Acpt_onclick
 * @descriptions : scwin.btn_Acpt_onclick
 * @returns {void}
 * @hidden N
 */
scwin.btn_Acpt_onclick = async function(e) {
    try {
        await scwin.receive("33");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40003.btn_Acpt_onclick" });
