 */
scwin.ibx_isurCdNm_onchange = async function (info) {
    // await scwin.listSync();
};

/**
 * @method
 * @event
 * @name grd_list_oncelldblclick
 * @description grd_list_oncelldblclick
 * @returns {void}
 * @hidden N
 */
scwin.grd_list_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        if(columnId === "chkYn") return;

        const stkoptDutyExerSeq = dlt_stockoptionRes.getCellData(rowIndex, "stkoptDutyExerSeq");

        // 공시부
        if (scwin.belngDepCd ==="2600" || scwin.belngDepCd ==="3400") {
            if(stkoptDutyExerSeq === "99999"){
                return;
            }
        // 2500 유가상장부, 3300 코스닥 상장부
        }else if(scwin.belngDepCd ==="2500" || scwin.belngDepCd ==="3300"){
            if(stkoptDutyExerSeq !== "99999"){
                return;
            }
        }

        if (rowIndex >= 0 ) { // 그리드에서 선택시
            scwin.setBzProcsNo(rowIndex);
        }

        if ("34" === scwin.clickListProcsStatCd){ // 수정요청리스트 호출
            // 수정요청 리스트 팝업창
            scwin.opeonPopup1();
            return;
        }

        // 2500 유가상장부, 3300 코스닥 상장부
        if(scwin.belngDepCd ==="2500" || scwin.belngDepCd ==="3300" || scwin.depCd  === 'ZSYS'){ // 상세내역 호출
            scwin.isGongsi = false;

            scwin.selBzProcsNo =  dlt_stockoptionRes.getCellData(rowIndex, "bzProcsNo");
            scwin.selPrtDepoId =  dlt_stockoptionRes.getCellData(rowIndex, "prtdepoId");
            scwin.selExerSeq   = dlt_stockoptionRes.getCellData(rowIndex, "stkoptDutyExerSeq");

            scwin.opeonPopup("U"); // 주식매수선택권 의무보유 관리 상세내역

        }

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40003.grd_list_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @func
 * @name scwin.listSync
 * @description 조회
 * @returns {void}
 * @hidden N
 */
scwin.listSync = async function() {

    const options = {
        validateType : "alert",
        checkType : "single",
        focus : true,
        fields : {
            acb_isurCd  : { required : true,   name : "[회사]" },
            }
    };

    const chkValidation = await $c.validate.validateDataCollect(grp_search, options);

    if (!chkValidation) {
        return false;
    }

    // if(acb_isurCd.getValue() === "") $c.win.alert("회사는 필수 입력입니다.");

    // dma_searchReq.set("isurCd",acb_isurCd.getValue());
    dma_searchReq.set("ldMktTpCd",scwin.market);

    const sbmOptions = {
        id : "sbm_stockoptionList",
        action : "/api/listing/lstmgt/stockoption/select-list",
        method : "get",
        ref : "dma_searchReq",
        target : "dlt_stockoptionRes=body",
        gridview : "grd_list",
        isProcessMsg : true
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success === true) {

        dlt_stockoptionRes.setBroadcast(false);
        for(i =0; i < dlt_stockoptionRes.getRowCount(); i++) {
            // console.log(dlt_stockoptionRes.getCellData(i, "stkoptDutyExerPayDd"));
            if(dlt_stockoptionRes.getCellData(i, "stkoptDutyExerPayDd") !== ""){
                dlt_stockoptionRes.setCellData(i, "stkoptDutyHdInputTpNm", "");
                dlt_stockoptionRes.setCellData(i, "comAbbrv", "");
                dlt_stockoptionRes.setCellData(i, "prtdepoPrnTpNm", "");
                dlt_stockoptionRes.setCellData(i, "nm", "");
                dlt_stockoptionRes.setCellData(i, "resdbzRegNo", "");
                dlt_stockoptionRes.setCellData(i, "stkoptDutyResolDd", "");
                dlt_stockoptionRes.setCellData(i, "prtdepoObjKindNm", "");
                dlt_stockoptionRes.setCellData(i, "stkoptDutyTotGrntShrs", "");
                dlt_stockoptionRes.setCellData(i, "stkoptDutyExerStrtDd", "");
                dlt_stockoptionRes.setCellData(i, "stkoptDutyExerEndDd", "");
                dlt_stockoptionRes.setCellData(i, "prtdepoEndDd", "");
                // dlt_stockoptionRes.setCellData(i, "listProcsStatNm", "");
            }

        }
        dlt_stockoptionRes.setBroadcast(true, true);

    }

};

/**
 * @method
 * @name receive
 * @description 접수 처리를 실행한다.
 * @param {String} type 구분 값
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.receive = async function(type) {
    let typeString = "";

    if (type === "33") {
    typeString = "접수";
    }  else { // 37
    typeString = "반려";
    }

    if (scwin.checkChecked().length > 0) {
        if( scwin.checkProcsStatCd() ){
            const vAnswer = await $c.win.confirm("선택된 항목을 모두 " + typeString + "처리 하시겠습니까?");
            if (vAnswer) {

                let checkedIndexList = grd_list.getCheckedJSON("chkYn");

                let jsonData = {
                    listProcsStatCd : ""
                    ,listBzTpCd  : ""
                    ,stkOptProcessDto : []
                }

                for (let i = 0; i < checkedIndexList.length; i++) {

                    jsonData.listProcsStatCd = type;
                    jsonData.listBzTpCd   = "770";

                    jsonData.stkOptProcessDto.push({
                        bzProcsNo : checkedIndexList[i].bzProcsNo
                        , chkYn : "T"
                        , follwBzProcsNo : checkedIndexList[i].follwBzProcsNo
                    });
                }

                const sbmOptions = {
                        id : "sbm_rejectOrProcesss",
                        action : "/api/listing/lstmgt/stockoption/process-stkopt",
                        method : "post",
                        ref : "dma_rejectOrAcceptReq",
                        isProcessMsg : true
                };

                const res =  await $c.sbm.executeDynamic(sbmOptions,jsonData);
                if (res.responseJSON.success === true) {
                    await $c.win.alert(typeString+"처리 성공했습니다");
                    await scwin.listSync();
                }
            }
        }
    }
};

