///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @func
 * @name scwin.checkOnly
 * @description scwin.checkOnly
 * @returns {void}
 * @hidden N
 */
scwin.checkOnly = function(selRow, bCheck) {
    let checked = "";
    if (bCheck === 1) {
        for (let i = 1; i <= dts_List.CountRow; i++) {

            checked = dts_List.NameValue(i, "CHK_YN");

            if (selRow === i) continue;
        }
    }
};

/**
 * @method
 * @func
 * @name scwin.checkChecked
 * @description scwin.checkChecked
 * @returns {void}
 * @hidden N
 */
scwin.checkChecked = function() {
    let rowPos = 0;

    rowPos = grd_list.getCheckedIndex("chkYn");

    if (rowPos.length === 0) {
        $c.win.alert("선택된 항목이 없습니다.");
    }

    return rowPos;
};

/**
 * @method
 * @func
 * @name scwin.checkProcsStatCd
 * @description scwin.checkProcsStatCd
 * @returns {void}
 * @hidden N
 */
scwin.checkProcsStatCd = function() {

    let listProcsStatCd = "";
    const isPass = true;

    scwin.checkedIndexList = grd_list.getCheckedJSON("chkYn");

    for (let i = 0; i < scwin.checkedIndexList.length; i++) {
        listProcsStatCd = scwin.checkedIndexList[i].listProcsStatCd;

        if (listProcsStatCd !== "32") {
            $c.win.alert("처리상태가 제출완료인 항목만 처리가능합니다.");
            return false;
        }
    }
    return isPass;
};

/**
 * @method
 * @func
 * @name scwin.checkValid
 * @description :그리드 체크박스 클릭했을때 validation
 * @returns {void}
 * @hidden N
 */
scwin.checkValid = function(selRow, bCheck) {

    if (bCheck === 1) {
        let stkoptDutyExerSeq = dlt_stockoptionRes.getCellData(selRow, "stkoptDutyExerSeq");
        // 2600 유가공시부, 3400 코스닥공시부
        if (scwin.belngDepCd === "2600" || scwin.belngDepCd === "3400") {
            if (stkoptDutyExerSeq === "99999") {
                $c.win.alert("대상자는 상장부에서만 선택할수 있습니다");
                dlt_stockoptionRes.setCellData(selRow, "chkYn", "0")
            }
        // 2500 유가상장부, 3300 코스닥 상장부
        } else if (scwin.belngDepCd === "2500" || scwin.belngDepCd === "3300") {
            if (stkoptDutyExerSeq !== "99999") {
                $c.win.alert("납입일은 공시부에서만 선택할수 있습니다.");
                dlt_stockoptionRes.setCellData(selRow, "chkYn", "0")
            }
        }
    }
};

/**
 * @method
 * @name checkIsurCd
 * @description 발행회사 코드 입력값을 확인한다.
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.checkIsurCd = function() {
    const isurCd = txb_ISUR_CD.getValue();
    if (isurCd.length > 0) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name setBzProcsNo
 * @description 업무처리번호를 화면 상태값에 설정한다.
 * @param {Number} rowIndex 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(rowIndex) {

    scwin.clickBzProcsNo = dlt_stockoptionRes.getCellData(rowIndex, "bzProcsNo");
    scwin.clickListProcsStatCd = dlt_stockoptionRes.getCellData(rowIndex, "listProcsStatCd");

    let stkoptDutyExerSeq =  dlt_stockoptionRes.getCellData(rowIndex, "stkoptDutyExerSeq");

    if (stkoptDutyExerSeq !== "99999") {
        scwin.clickBzProcsNo = dlt_stockoptionRes.getCellData(rowIndex, "follwBzProcsNo");
    }
};

/**
 * @method
 * @name opeonPopup1
 * @description 주식매수선택권 의무보유 수정요청 리스트팝업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.opeonPopup1 = async function() {

    const popupData = {
        "bzProcsNo" : scwin.clickBzProcsNo                       
    };

    let url = "/ui/lst/lstmgt/ULDSTF40005.xml";
    let popTitle = "주식매수선택권 의무보유 수정요청 리스트";

    const opts = {
        id: "ULDSTF40005",
        popupName: popTitle,
        width: 1000,
        height: 350,
        frameModal: "top",
    };

    await $c.win.openPopup(url, opts, popupData);
    await scwin.listSync();
}

/**
 * @method
 * @name opeonPopup
 * @description 주식매수선택권 의무보유 관리 상세내역 등록 팝업
 * @param {*} text text
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.opeonPopup = async function(text) {

    const disPlayFlagVal = text;

    const popupData = {
        "prtdepoId" : scwin.selPrtDepoId,                          
        "exerSeq" :   scwin.selExerSeq,
        "disPlayFlag" : disPlayFlagVal
    };
    let url = "/ui/lst/lstmgt/ULDSTF40004.xml";
    let popTitle = "주식매수선택권 의무보유 관리 상세내역 등록";

    const opts = {
        id: "ULDSTF40004",
        popupName: popTitle,
        width: 1000,
        height: 680,
        frameModal: "top",
    };

    const res = await $c.win.openPopup(url, opts, popupData);
    if (res === 200 ){
        await scwin.listSync();
    }
}
